<template>
  <div class="oj-admin">
    <header class="oj-admin-hero"><h2>算法题库</h2></header>
    <div class="oj-overview"><div><span class="oj-stat-icon blue"><OjIcon name="library"  /></span><section><small>{{ keyword || difficulty ? '符合筛选的题目' : '题库题目' }}</small><strong>{{ total }} <em>道</em></strong></section></div><div><span class="oj-stat-icon green"><OjIcon name="circle-check"  /></span><section><small>当前页已发布</small><strong>{{ rows.filter(r=>r.status==='PUBLISHED' && r.validated).length }} <em>道</em></strong></section></div><div><span class="oj-stat-icon violet"><OjIcon name="language"  /></span><section><small>已启用语言</small><strong>{{ settings.filter(l=>l.enabled).length }} <em>/ {{ settings.length }}</em></strong></section></div><div><span :class="['oj-stat-icon',health.available?'green':'amber']"><OjIcon name="connection"  /></span><section><small>判题服务 · {{ health.queued || 0 }} 个等待任务</small><strong class="oj-service-state">{{ health.available?'运行正常':'暂不可用' }}<i :class="{online:health.available}" /></strong></section></div></div>
    <el-tabs v-model="activeTab" class="oj-main-tabs">
      <el-tab-pane label="题目管理" name="problems"><template #label><OjIcon name="library" :size="16" /> 题目管理</template>
        <div class="oj-section-heading"><div><h3>题目管理</h3><p>维护题目内容、测试数据和发布状态。</p></div><span class="oj-section-meta">{{ total }} 道题目</span></div>
        <div class="oj-admin-toolbar oj-list-toolbar"><el-input v-model="keyword" placeholder="搜索题目、标签或来源" clearable @keyup.enter="page=1;load()" /><el-select v-model="difficulty" placeholder="全部难度" clearable @change="page=1;load()"><el-option v-for="(label,key) in levels" :key="key" :label="label" :value="key" /></el-select><OjActionButton @click="page=1;load()" icon="search">搜索</OjActionButton><OjActionButton type="primary" @click="create" icon="plus">新建题目</OjActionButton><OjActionButton @click="fileInput.click()" icon="upload">导入题目包</OjActionButton><OjActionButton @click="openOrder" icon="sort">调整展示顺序</OjActionButton><input ref="fileInput" type="file" accept=".json,application/json" hidden @change="importPack" /></div>
        <div class="oj-publish-flow"><span><i>1</i> 保存草稿</span><OjIcon name="chevron-right" :size="14" /><span><i>2</i> 验证全部语言与模式 · 3 轮</span><OjIcon name="chevron-right" :size="14" /><span><i>3</i> 发布题目</span><small>修改内容或限制后需重新验证</small></div>
        <el-table v-loading="loading" :data="rows" class="oj-problem-table" row-key="id" style="margin-top:18px">
          <el-table-column prop="sortOrder" label="顺序" width="70"><template #default="{row}">{{ Number(row.sortOrder)+1 }}</template></el-table-column><el-table-column label="题目" min-width="220"><template #default="{row}"><div class="oj-table-title"><span class="oj-problem-symbol"><OjIcon name="code" :size="22" /></span><div><OjActionButton link icon="edit" class="oj-title-action" @click="edit(row.id)">{{ row.title }}</OjActionButton><small>{{ row.sourcePlatform }}<span v-if="row.sourceId"> · {{ row.sourceId }}</span> <span v-if="row.tags?.length"> · {{ row.tags.slice(0,2).join(' / ') }}</span></small></div></div></template></el-table-column><el-table-column label="难度" width="85"><template #default="{row}"><el-tag :type="row.difficulty === 'EASY' ? 'success' : row.difficulty === 'HARD' ? 'danger' : 'warning'">{{ levels[row.difficulty] }}</el-tag></template></el-table-column>
          <el-table-column label="模式" width="145"><template #default="{row}"><div class="oj-table-modes"><span v-for="m in row.modes" :key="m">{{ m==='FUNCTION'?'核心函数':'完整程序' }}</span></div></template></el-table-column><el-table-column label="测试集" width="85"><template #default="{row}"><span class="oj-test-count">{{ row.testCount }}</span><small class="oj-muted"> 组</small></template></el-table-column>
          <el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED' && row.validated ? 'success' : row.status==='DISABLED' ? 'danger' : 'info'">{{ ['PUBLISHED','CONTEST_ONLY'].includes(row.status) && !row.validated ? '需重新验证' : states[row.status] }}</el-tag></template></el-table-column>
          <el-table-column label="操作" min-width="310"><template #default="{row}"><div class="oj-row-actions"><OjActionButton link type="primary" @click="edit(row.id)" icon="edit">编辑</OjActionButton><OjActionButton link type="primary" @click="edit(row.id,'tests')" icon="cases">测试集</OjActionButton><OjActionButton link type="primary" icon="library" @click="solutionId=row.id;solutionOpen=true">题解</OjActionButton><OjActionButton link type="primary" :disabled="validating.has(row.id)" @click="validate(row)" icon="check">{{ validating.has(row.id) ? '验证中' : '验证' }}</OjActionButton><el-dropdown trigger="click" popper-class="oj-actions-menu"><OjActionButton link class="oj-more-action" icon="more">更多 </OjActionButton><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="row.status!=='PUBLISHED'" :disabled="!row.validated" @click="setStatus(row,'PUBLISHED')"><OjIcon name="play" :size="16" />发布题目</el-dropdown-item><el-dropdown-item v-if="row.status!=='CONTEST_ONLY'" :disabled="!row.validated" @click="setStatus(row,'CONTEST_ONLY')"><OjIcon name="shield" :size="16" />仅管理端可见</el-dropdown-item><el-dropdown-item v-if="['PUBLISHED','CONTEST_ONLY'].includes(row.status)" @click="setStatus(row,'DRAFT')"><OjIcon name="download" :size="16" />下架题目</el-dropdown-item><el-dropdown-item :divided="row.status==='PUBLISHED' || row.validated" @click="setStatus(row,row.status==='DISABLED'?'DRAFT':'DISABLED')"><OjIcon name="ban" :size="16" />{{ row.status==='DISABLED'?'解除禁用':'禁用题目' }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column>
        </el-table>
        <el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load" />
      </el-tab-pane>
      <el-tab-pane label="题单管理" name="sets"><template #label><OjIcon name="file" :size="16" /> 题单管理</template><OjProblemSets v-if="activeTab==='sets'" @edit-problem="edit" /></el-tab-pane>
      <el-tab-pane label="统一管理" name="settings"><template #label><OjIcon name="settings" :size="16" /> 统一管理</template>
        <OjNodeManager v-if="activeTab==='settings'" />
        <div class="oj-section-heading"><div><h3>语言与运行配置</h3><p>统一管理可用语言及每次运行的资源限制。</p></div><OjActionButton @click="loadSettings" icon="refresh">刷新状态</OjActionButton></div>
        <div class="oj-admin-toolbar oj-health-strip"><el-tag :type="health.available?'success':'danger'">判题服务{{ health.available?'正常':'不可用' }}</el-tag><span>{{ settings.filter(l=>l.enabled).length }} / {{ settings.length }} 种语言已启用 · 等待任务 {{ health.queued || 0 }}</span></div>
        <el-alert type="warning" :closable="false" title="保存新的语言启用状态或资源限制后，题目需要按新配置验证才能继续展示。运行版本由镜像固定。" />
        <el-table :data="settings" class="oj-language-table" style="margin-top:18px"><el-table-column label="语言" width="135"><template #default="{row}"><span class="oj-language-icon">{{ languageBadges[row.languageKey] }}</span><strong>{{ row.label }}</strong></template></el-table-column><el-table-column prop="version" label="运行版本" min-width="240" /><el-table-column label="启用" width="100"><template #default="{row}"><el-switch v-model="row.enabled" /></template></el-table-column><el-table-column label="时间限制（ms）" width="210"><template #default="{row}"><el-input-number v-model="row.timeLimitMs" :min="100" :max="10000" :step="100" /></template></el-table-column><el-table-column label="内存限制（MiB）" width="210"><template #default="{row}"><el-input-number v-model="row.memoryLimitMb" :min="row.languageKey==='java'?128:32" :max="384" :step="32" /></template></el-table-column></el-table>
        <div class="oj-settings-footer"><p class="oj-admin-note">版本随平台镜像更新；限制配置保存后生效。</p><OjActionButton type="primary" @click="saveSettings" icon="save">保存语言配置</OjActionButton></div>
      </el-tab-pane>
      <el-tab-pane label="判题日志与队列" name="monitor"><template #label><OjIcon name="timeline" :size="16" /> 判题日志与队列</template>
        <div class="oj-section-heading"><div><h3>判题运行台</h3><p>查看每一次代码运行与提交，追踪任务的完整执行过程。</p></div><OjActionButton :loading="monitorLoading" @click="loadMonitor" icon="refresh">刷新</OjActionButton></div>
        <p v-if="monitorError" role="alert" class="oj-monitor-error">{{ monitorError }}</p>
        <div class="oj-monitor-summary"><div><small>判题服务</small><strong class="oj-live-health"><i :class="{online:monitor.health?.available}" />{{ monitor.health?.available?'运行正常':'暂不可用' }}</strong><span>{{ monitor.workers || 0 }} 个并发任务位 · 实时更新</span></div><div><small>正在执行</small><strong>{{ monitor.queue?.filter(r=>r.status==='RUNNING').length || 0 }} <em>个任务</em></strong><span>编译与用例执行</span></div><div><small>等待队列</small><strong>{{ monitor.health?.queued || 0 }} <em>/ {{ monitor.capacity || 50 }}</em></strong><span>已入队，等待执行</span></div></div>
        <div class="oj-monitor-nav"><div role="group" aria-label="监控视图"><button :class="{active:monitorView==='history'}" @click="monitorView='history'"><OjIcon name="history" :size="16" />运行记录 <small>{{ monitor.total || 0 }}</small></button><button :class="{active:monitorView==='queue'}" @click="monitorView='queue'"><OjIcon name="queue" :size="16" />当前队列 <small>{{ monitor.queue?.length || 0 }}</small></button></div><span>每 5 秒刷新 · 点击记录查看过程</span></div>
        <el-table :data="monitorView==='queue'?monitor.queue || []:monitor.records || []" class="oj-runtime-table" row-key="id" empty-text="暂无任务记录" @row-click="openRun">
          <el-table-column label="任务 / 题目" min-width="170"><template #default="{row}"><div class="oj-run-title"><small>#{{ row.id }}</small><strong>{{ row.problemTitle || '题目已移除' }}</strong></div></template></el-table-column>
          <el-table-column label="提交用户" min-width="170"><template #default="{row}"><div class="oj-run-user"><strong>{{ row.name || '未知用户' }} <small v-if="row.nickname">（{{ row.nickname }}）</small></strong><span>{{ row.studentId || '账号已移除' }}</span></div></template></el-table-column>
          <el-table-column label="运行内容" min-width="145"><template #default="{row}"><div class="oj-run-context"><strong>{{ kindNames[row.kind] || row.kind }}</strong><small>{{ languageNames[row.language] || '—' }} · {{ modeNames[row.mode] || '—' }}</small><small>{{ row.nodeName || '等待分配节点' }}</small></div></template></el-table-column>
          <el-table-column label="判题结果" min-width="155"><template #default="{row}"><OjStatusBadge :status="row.status" /><div v-if="Number(row.totalCases)>0" class="oj-run-progress"><span>{{ row.passedCases }} / {{ row.totalCases }}</span><i><b :style="{width:caseProgress(row)+'%'}" /></i></div></template></el-table-column>
          <el-table-column label="提交时间 / 耗时" min-width="190"><template #default="{row}"><div class="oj-run-context"><strong>{{ formatOjDate(row.createdAt) }}</strong><small>等待 {{ row.waitSeconds }} s · 运行 {{ row.durationSeconds ?? '—' }} s</small></div></template></el-table-column>
          <el-table-column width="135"><template #default="{row}"><OjActionButton link type="primary" class="oj-detail-link" @click.stop="openRun(row)" icon="timeline">查看过程 </OjActionButton></template></el-table-column>
        </el-table>
        <el-pagination v-if="monitorView==='history'" v-model:current-page="monitorPage" :page-size="20" :total="Number(monitor.total || 0)" layout="total, prev, pager, next" @current-change="loadMonitor" />
      </el-tab-pane>
    </el-tabs>
    <OjSolutionEditor v-if="solutionOpen" v-model:open="solutionOpen" :problem-id="solutionId" />
    <el-dialog align-center v-model="runOpen" title="运行过程" width="min(760px,95vw)" class="oj-run-dialog">
      <p v-if="runError" class="oj-monitor-error" role="alert">{{ runError }} <OjActionButton link @click="loadRun" icon="refresh">重试</OjActionButton></p>
      <div v-if="runLoading && !runDetail" class="oj-run-loading">正在加载任务过程…</div>
      <template v-if="runDetail"><div class="oj-run-detail-heading"><div><small>任务 #{{ runDetail.task.id }} · {{ kindNames[runDetail.task.kind] }}</small><h3>{{ runDetail.task.problemTitle }}</h3><p>{{ runDetail.task.name }}（{{ runDetail.task.nickname }}）<span>{{ runDetail.task.studentId }}</span></p></div><OjStatusBadge :status="runDetail.task.status" /></div><div class="oj-run-detail-meta"><span>{{ languageNames[runDetail.task.language] }} · {{ modeNames[runDetail.task.mode] }}</span><span>等待 {{ runDetail.task.waitSeconds }} s</span><span>运行 {{ runDetail.task.durationSeconds ?? '—' }} s</span><span>{{ runDetail.task.passedCases }} / {{ runDetail.task.totalCases }} 用例</span></div>
        <div class="oj-run-content-tabs"><button :class="{active:runTab==='timeline'}" @click="runTab='timeline'"><OjIcon name="timeline" :size="16" />运行时间线</button><button :class="{active:runTab==='code'}" @click="loadRunCode"><OjIcon name="code" :size="16" />提交的代码</button></div>
        <div v-if="runTab==='code'" class="oj-run-code"><p v-if="codeLoading" class="oj-format-loading" role="status">正在读取并格式化提交代码…</p><template v-else-if="runCode"><div class="oj-run-code-toolbar"><span>{{ languageNames[runCode.language] }} · {{ modeNames[runCode.mode] }} · {{ runCode.code.length }} 字符</span><OjActionButton v-if="runCode.code" size="small" :icon="runShowRaw?'format':'file'" :aria-pressed="runShowRaw" @click="runShowRaw=!runShowRaw">{{ runShowRaw?'格式化显示':'查看原始代码' }}</OjActionButton></div><p v-if="runFormatError" class="oj-monitor-error" role="status">{{ runFormatError }}，已保留原始代码。</p><OjCodeEditor v-if="runCode.code" :model-value="runShowRaw?runCode.code:runDisplayCode" :language="runCode.language" read-only label="本次提交的代码" /><p v-else>该任务是平台验证，使用题目配置中的参考解。</p></template></div>
        <TransitionGroup v-else name="oj-timeline" tag="ol" class="oj-run-timeline" aria-label="任务执行时间线"><li v-for="(step,i) in runDetail.timeline" :key="step.id" :class="{error:step.level==='ERROR' || (step.event==='FINISHED' && step.status!=='AC'),active:i===runDetail.timeline.length-1 && runActive}"><span class="oj-timeline-dot"><OjIcon v-if="step.event==='FINISHED'" :name="step.status==='AC'?'check':'alert'" :size="16" /><span v-else>{{ i+1 }}</span></span><div><div class="oj-timeline-title"><strong>{{ step.event==='FINISHED'?(ojStatuses[step.status]?.label || '执行结束'):eventNames[step.event] || step.event }}</strong><time>{{ formatOjDate(step.createdAt) }}</time></div><p>{{ timelineHelp(step) }}</p><small v-if="step.nodeName">执行节点：{{ step.nodeName }}</small><small v-if="step.historical">根据历史任务时间恢复</small></div></li><li v-if="runActive" key="live" class="oj-timeline-live"><span class="oj-timeline-dot"><i /></span><div><strong>{{ runDetail.task.status==='QUEUED'?'等待开始运行':'任务执行中' }}</strong><p>页面自动更新，任务完成后显示最终结果。</p></div></li></TransitionGroup>
      </template><template #footer><span v-if="runActive" class="oj-live-caption"><i /> 正在追踪任务状态</span><OjActionButton @click="runOpen=false" icon="close">关闭</OjActionButton></template>
    </el-dialog>
    <el-dialog align-center v-model="orderOpen" title="调整题目展示顺序" width="min(700px,95vw)"><p class="oj-admin-note">包含草稿与禁用题目。点击上移、下移调整，保存后用户端和管理端按此顺序展示。</p><div v-for="(item,i) in orderRows" :key="item.id" class="oj-order-row"><span>{{ i+1 }}</span><strong>{{ item.title }}</strong><el-tag type="info">{{ states[item.status] }}</el-tag><OjActionButton size="small" :disabled="i===0 || orderSaving" :aria-label="`上移 ${item.title}`" @click="moveOrder(i,-1)" icon="arrow-up" circle /><OjActionButton size="small" :disabled="i===orderRows.length-1 || orderSaving" :aria-label="`下移 ${item.title}`" @click="moveOrder(i,1)" icon="arrow-down" circle /></div><template #footer><OjActionButton @click="orderOpen=false" icon="close">取消</OjActionButton><OjActionButton type="primary" :loading="orderSaving" @click="saveOrder" icon="save">保存展示顺序</OjActionButton></template></el-dialog>
    <el-dialog align-center v-model="editorOpen" :title="editingId ? '编辑题目' : '新建题目'" width="min(1100px, 95vw)" class="oj-admin-dialog" :close-on-click-modal="false">
      <div class="oj-editor-summary"><span class="oj-problem-symbol"><OjIcon name="code" :size="22" /></span><div><strong>{{ pack.title || '开始创建一道新题' }}</strong><small>{{ pack.sourcePlatform }} · {{ levels[pack.difficulty] }} · {{ pack.cases.length }} 组测试数据</small></div><el-tag type="info" effect="plain">保存为草稿</el-tag></div>
      <el-tabs v-model="editorTab" class="oj-editor-tabs">
        <el-tab-pane label="题目内容" name="content"><template #label><OjIcon name="file" :size="16" /> 题目内容</template><el-form label-position="top" class="oj-admin-form">
          <div class="oj-form-section-title"><span>01</span><div><strong>基本信息</strong><small>为题目选择标题、难度和检索标签</small></div></div><div class="oj-form-grid"><el-form-item label="题目标识"><el-input v-model="pack.slug" placeholder="例如 leetcode-1" /></el-form-item><el-form-item label="标题"><el-input v-model="pack.title" maxlength="200" /></el-form-item><el-form-item label="难度"><el-select v-model="pack.difficulty"><el-option v-for="(label,key) in levels" :key="key" :label="label" :value="key" /></el-select></el-form-item><el-form-item label="标签（逗号分隔）"><el-input v-model="tagsText" /></el-form-item></div>
          <div class="oj-form-section-title"><span>02</span><div><strong>题目与数据规范</strong><small>清晰描述输入、输出和边界条件</small></div></div><el-form-item label="题目描述"><el-input v-model="pack.description" type="textarea" :rows="6" /></el-form-item><div class="oj-form-grid"><el-form-item label="输入格式"><el-input v-model="pack.inputFormat" type="textarea" :rows="3" /></el-form-item><el-form-item label="输出格式"><el-input v-model="pack.outputFormat" type="textarea" :rows="3" /></el-form-item></div><el-form-item label="数据范围与边界条件"><el-input v-model="pack.constraints" type="textarea" :rows="3" /></el-form-item>
          <div class="oj-form-section-title"><span>03</span><div><strong>来源与署名</strong><small>保留原题链接及题目、测试数据的来源说明</small></div></div><div class="oj-form-grid"><el-form-item label="来源平台"><el-select v-model="pack.sourcePlatform" filterable allow-create><el-option v-for="source in ['LeetCode','洛谷','牛客','原创']" :key="source" :value="source" :label="source" /></el-select></el-form-item><el-form-item label="来源题号"><el-input v-model="pack.sourceId" /></el-form-item></div><el-form-item label="来源链接（原创题可留空）"><el-input v-model="pack.sourceUrl" placeholder="https://…" /></el-form-item><el-form-item label="题目及测试数据来源说明"><el-input v-model="pack.sourceNote" type="textarea" :rows="3" placeholder="注明原题或改编来源、原创作者，以及公开样例/自行生成测试数据的来源。" /></el-form-item>
          <div class="oj-form-section-title"><span>04</span><div><strong>做题与判题方式</strong><small>决定用户可以选择的模式及答案比较规则</small></div></div><div class="oj-form-grid"><el-form-item label="允许的做题模式"><el-checkbox-group v-model="pack.modes"><el-checkbox value="STDIO">完整程序</el-checkbox><el-checkbox value="FUNCTION">核心函数</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="默认模式"><el-select v-model="pack.defaultMode"><el-option v-for="m in pack.modes" :key="m" :value="m" :label="m==='FUNCTION'?'核心函数':'完整程序'" /></el-select></el-form-item></div>
          <el-form-item label="答案比较"><el-select v-model="pack.checker"><el-option value="TOKENS" label="按顺序比较单词/数字（忽略空白）" /><el-option value="UNORDERED_TOKENS" label="忽略单词/数字顺序（例如两数之和的下标）" /></el-select></el-form-item>
        </el-form></el-tab-pane>
        <el-tab-pane :label="`测试集（${pack.cases.length}）`" name="tests">
          <div class="oj-test-summary"><div><strong>{{ pack.cases.length }}</strong><span>全部测试</span></div><div><strong>{{ pack.cases.filter(c=>c.sample).length }}</strong><span>公开样例</span></div><div><strong>{{ pack.cases.filter(c=>!c.sample).length }}</strong><span>隐藏测试</span></div><p>公开样例帮助理解题意，隐藏测试检验边界与正确性。</p></div>
          <div class="oj-admin-toolbar"><OjActionButton type="primary" @click="addCase" icon="plus">新增用例</OjActionButton><OjActionButton @click="caseInput.click()" icon="upload">导入测试集 JSON</OjActionButton><OjActionButton @click="exportCases" icon="download">导出测试集</OjActionButton><input ref="caseInput" type="file" accept=".json,application/json" hidden @change="importCases" /><span>{{ pack.cases.filter(c=>c.sample).length }} 个公开样例</span></div>
          <el-alert title="标记为样例的输入、输出会公开给用户。其他用例只用于提交判题。测试集编辑后，请保存题目并重新验证。" type="info" :closable="false" />
          <el-table :data="caseRows" class="oj-case-table"><el-table-column label="名称" width="170"><template #default="{row}"><el-input v-model="row.name" /></template></el-table-column><el-table-column label="输入" min-width="220"><template #default="{row}"><el-input v-model="row.input" type="textarea" :rows="3" /></template></el-table-column><el-table-column label="期望输出" min-width="220"><template #default="{row}"><el-input v-model="row.expectedOutput" type="textarea" :rows="3" /></template></el-table-column><el-table-column label="样例" width="70"><template #default="{row}"><el-checkbox v-model="row.sample" /></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><OjActionButton link type="danger" @click="pack.cases.splice(pack.cases.indexOf(row),1)" icon="trash">删除</OjActionButton></template></el-table-column></el-table>
          <el-pagination v-model:current-page="casePage" :page-size="10" :total="pack.cases.length" layout="total, prev, pager, next" />
        </el-tab-pane>
        <el-tab-pane label="语言模板与参考解" name="templates"><template #label><OjIcon name="code" :size="16" /> 语言模板与参考解</template>
          <div class="oj-template-languages" role="group" aria-label="模板语言"><button v-for="l in settings" :key="l.languageKey" :class="{active:profileLanguage===l.languageKey}" :aria-pressed="profileLanguage===l.languageKey" @click="profileLanguage=l.languageKey"><OjIcon name="code" :size="16" />{{ l.label }}</button></div>
          <div class="oj-template-top"><div class="oj-template-modes" role="group" aria-label="模板模式"><button v-for="m in pack.modes" :key="m" :class="{active:templateMode===m}" :aria-pressed="templateMode===m" @click="templateMode=m"><OjIcon :name="m==='FUNCTION'?'code':'terminal'" :size="16" />{{ m==='FUNCTION'?'核心函数':'完整程序' }}</button></div><span>{{ settings.find(l=>l.languageKey===profileLanguage)?.version }}</span></div>
          <div class="oj-template-workbench"><div class="oj-template-files"><button v-for="f in templateFiles" :key="f.key" :class="{active:templateField===f.key}" @click="templateField=f.key"><OjIcon name="file" />{{ f.label }}</button></div><div class="oj-template-description"><div><strong>{{ activeTemplate?.label }}</strong><p>{{ activeTemplate?.help }}</p></div><OjActionButton size="small" :loading="formatting" :disabled="templatesLoading" @click="formatSelected" icon="format">格式化代码</OjActionButton></div><div v-if="templatesLoading" class="oj-format-loading">正在格式化五种语言的模板与参考解…</div><OjCodeEditor v-if="profile" :key="profileLanguage+templateMode+templateField" v-model="selectedCode" :language="profileLanguage" :read-only="templatesLoading" :label="activeTemplate?.label" /><div class="oj-template-footer"><span>{{ selectedCode.length }} 字符 · {{ selectedCode.split('\n').length }} 行</span><span>支持语法高亮、行号与 Tab 缩进</span></div></div>
        </el-tab-pane>
      </el-tabs>
      <template #footer><OjActionButton @click="editorOpen=false" icon="close">取消</OjActionButton><OjActionButton v-if="editingId" @click="showLatestReport" icon="history">查看验证记录</OjActionButton><OjActionButton type="primary" :loading="saving" :disabled="templatesLoading" @click="save" icon="save">保存为草稿</OjActionButton></template>
    </el-dialog>
    <el-dialog align-center v-model="reportOpen" title="发布验证" width="min(820px,95vw)"><template v-if="report"><div class="oj-report-summary"><span class="oj-report-symbol"><OjIcon name="circle-check" v-if="report.status==='AC'"  /><OjIcon name="stats" v-else  /></span><div><OjStatusBadge :status="report.status" /><p>{{ report.passedCases }} / {{ report.totalCases }} 个用例通过</p></div></div><el-progress :percentage="report.totalCases?Math.min(100,Math.round(report.passedCases/report.totalCases*100)):0" :status="report.status==='AC'?'success':undefined" :stroke-width="8" /><p v-if="report.result?.message">{{ report.result.message }}</p><div v-for="r in report.result?.reports || []" :key="r.language+r.mode" class="oj-validation-row"><strong>{{ languageNames[r.language] }} · {{ modeNames[r.mode] }} <OjStatusBadge :status="r.result.verdict" /></strong><span>{{ r.result.passedCases }}/{{ r.result.totalCases }} · {{ r.result.timeMs }} ms</span><pre v-if="r.result.compilerOutput">{{ r.result.compilerOutput }}</pre></div></template></el-dialog>
  </div>
</template>
<script setup>
import OjActionButton from '@/components/OjActionButton.vue'
import OjIcon from '@/components/OjIcon.vue'
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import { ElMessage } from 'element-plus'
import request from '@/utils/request'
import OjStatusBadge from '@/components/OjStatusBadge.vue'
import OjNodeManager from '@/components/OjNodeManager.vue'
import OjSolutionEditor from '@/components/OjSolutionEditor.vue'
import OjProblemSets from '@/components/OjProblemSets.vue'
import { ojStatuses,languageNames,modeNames,kindNames,eventNames,formatOjDate } from '@/utils/ojDictionaries'
import OjCodeEditor from '@/components/OjCodeEditor.vue'
import { formatOjCode, formatOjPack } from '@/utils/ojFormatter'
const levels = { EASY:'简单', MEDIUM:'中等', HARD:'困难' }, states = { DRAFT:'草稿', PUBLISHED:'已发布', CONTEST_ONLY:'仅管理端可见', DISABLED:'已禁用' }
const activeTab=ref('problems'), rows=ref([]), page=ref(1), total=ref(0), keyword=ref(''), difficulty=ref(''), loading=ref(false), settings=ref([]), health=ref({})
const editorOpen=ref(false), editorTab=ref('content'), editingId=ref(null), revision=ref(null), pack=ref(blankPack()), tagsText=ref(''), profileLanguage=ref('cpp'), casePage=ref(1), saving=ref(false), fileInput=ref(null), caseInput=ref(null)
const solutionOpen=ref(false),solutionId=ref(null)
const reportOpen=ref(false), report=ref(null), validationJob=ref(null), validating=ref(new Set())
const profile=computed(()=>pack.value.profiles[profileLanguage.value]), caseRows=computed(()=>pack.value.cases.slice((casePage.value-1)*10,casePage.value*10))
const languageBadges={c:'C',cpp:'C++',java:'Java',python:'Py',rust:'Rs'}
const templateMode=ref('STDIO'),templateField=ref('starter'),formatting=ref(false),templatesLoading=ref(false)
const templateFiles=computed(()=>[{key:'starter',label:'初始模板',help:'用户开始练习或恢复模板时看到的代码。请保留清晰的函数签名和必要的注释。'},{key:'reference',label:'参考解',help:'用于发布前的完整测试验证，不向用户展示。'},...(templateMode.value==='FUNCTION'?[{key:'driver',label:'调用驱动',help:'负责读取输入、构造参数并输出结果。必须保留唯一的 __USER_CODE__ 标记。驱动会与用户代码一起执行，可被用户读取；请勿写入参考解、隐藏答案或密钥。'}]:[])])
const activeTemplate=computed(()=>templateFiles.value.find(f=>f.key===templateField.value))
const selectedCode=computed({get:()=>templateField.value==='reference'?pack.value.references[profileLanguage.value]?.[templateMode.value]||'':profile.value?.[templateField.value==='driver'?'functionDriver':templateMode.value==='FUNCTION'?'starterFunction':'starterStdio']||'',set:value=>{if(templateField.value==='reference')pack.value.references[profileLanguage.value][templateMode.value]=value;else profile.value[templateField.value==='driver'?'functionDriver':templateMode.value==='FUNCTION'?'starterFunction':'starterStdio']=value}})
watch(()=>pack.value.modes.slice(),m=>{if(!m.includes(templateMode.value))templateMode.value=m[0]||'STDIO'})
watch(templateMode,m=>{if(m==='STDIO'&&templateField.value==='driver')templateField.value='starter'})
async function formatSelected(){const original=selectedCode.value,key=profileLanguage.value+templateMode.value+templateField.value;formatting.value=true;try{const result=await formatOjCode(original,profileLanguage.value);if(key===profileLanguage.value+templateMode.value+templateField.value&&original===selectedCode.value)selectedCode.value=result}catch(e){ElMessage.warning(e.message)}finally{formatting.value=false}}
let formatGeneration=0
async function formatTemplates(){const generation=++formatGeneration,target=pack.value;templatesLoading.value=true;try{await formatOjPack(target)}catch(e){if(generation===formatGeneration)ElMessage.warning('部分代码未能格式化，请检查语法：'+e.message)}finally{if(generation===formatGeneration)templatesLoading.value=false}}
const monitor=ref({}),monitorLoading=ref(false),monitorError=ref(''),monitorPage=ref(1),orderOpen=ref(false),orderRows=ref([]),orderSaving=ref(false)
const monitorView=ref('history'),runOpen=ref(false),runDetail=ref(null),runLoading=ref(false),runError=ref('')
const runActive=computed(()=>['QUEUED','RUNNING'].includes(runDetail.value?.task.status))
const runTab=ref('timeline'),runCode=ref(null),codeLoading=ref(false),runDisplayCode=ref(''),runShowRaw=ref(false),runFormatError=ref('')
let codeGeneration=0
async function loadRunCode(){
  runTab.value='code';if(runCode.value||codeLoading.value)return
  const id=runId,generation=++codeGeneration;codeLoading.value=true;runFormatError.value=''
  const current=()=>generation===codeGeneration&&runId===id&&runOpen.value&&!disposed
  try{
    const {data}=await request.get(`/api/admin/oj/monitor/${id}/code`);if(!current())return
    runCode.value=data;runDisplayCode.value=data.code||''
    try{const formatted=await formatOjCode(data.code,data.language);if(current())runDisplayCode.value=formatted}
    catch(e){if(current())runFormatError.value=e.message}
  }catch(e){if(current())runError.value=e.message}
  finally{if(current())codeLoading.value=false}
}
let runId,runTimer,runGeneration=0
function caseProgress(row){return Number(row.totalCases)>0?Math.min(100,100*Number(row.passedCases)/Number(row.totalCases)):0}
function timelineHelp(step){return step.event==='FINISHED'?(ojStatuses[step.status]?.help || '任务已结束'):({QUEUED:'任务已加入判题队列，等待工作线程处理。',STARTED:'开始编译代码并执行测试集。',RECOVERED:'服务重启，恢复中断任务并重新加入队列。',NODE_ERROR:'节点连接中断，系统尝试分配其他可用节点。',REASSIGNED:'已切换节点，重新编译并运行本次提交。'}[step.event] || '任务状态已更新。')}
async function openRun(row){++codeGeneration;codeLoading.value=false;runTab.value='timeline';runCode.value=null;runDisplayCode.value='';runShowRaw.value=false;runFormatError.value='';runId=row.id;runDetail.value=null;runError.value='';runOpen.value=true;await loadRun()}
async function loadRun(){if(!runOpen.value || !runId)return;const generation=++runGeneration;runLoading.value=true;runError.value='';try{const {data}=await request.get(`/api/admin/oj/monitor/${runId}`);if(generation===runGeneration && runOpen.value && !disposed)runDetail.value=data}catch(e){if(generation===runGeneration)runError.value=e.message}finally{if(generation===runGeneration)runLoading.value=false}}
watch(runOpen,open=>{clearInterval(runTimer);if(open)runTimer=setInterval(()=>{if(runActive.value && !runLoading.value && !document.hidden)loadRun()},2500);else{++runGeneration;++codeGeneration;runLoading.value=false;codeLoading.value=false}})
let monitorTimer,orderExpected=[],monitorGeneration=0
async function loadMonitor(){const generation=++monitorGeneration;monitorLoading.value=true;monitorError.value='';try{const {data}=await request.get('/api/admin/oj/monitor',{params:{page:monitorPage.value}});if(generation===monitorGeneration&&!disposed){monitor.value=data;health.value=data.health}}catch(e){if(generation===monitorGeneration)monitorError.value=e.message}finally{if(generation===monitorGeneration)monitorLoading.value=false}}
watch(activeTab,value=>{clearInterval(monitorTimer);if(value==='monitor'){loadMonitor();monitorTimer=setInterval(()=>{if(!document.hidden&&!monitorLoading.value)loadMonitor()},5000)}})
async function openOrder(){try{const {data}=await request.get('/api/admin/oj/order');orderRows.value=data.records;orderExpected=data.records.map(r=>r.id);orderOpen.value=true}catch(e){ElMessage.error(e.message)}}
function moveOrder(i,direction){const next=[...orderRows.value];[next[i],next[i+direction]]=[next[i+direction],next[i]];orderRows.value=next}
async function saveOrder(){orderSaving.value=true;try{await request.put('/api/admin/oj/order',{expected:orderExpected,ids:orderRows.value.map(r=>r.id)});orderOpen.value=false;ElMessage.success('展示顺序已保存');load()}catch(e){ElMessage.error(e.message)}finally{orderSaving.value=false}}
const timers=new Set(); let disposed=false
function blankPack(){ const profiles={}, references={};for(const k of ['c','cpp','java','python','rust']){profiles[k]={starterStdio:'',starterFunction:'',functionDriver:''};references[k]={STDIO:'',FUNCTION:''}}return {slug:'',title:'',difficulty:'EASY',tags:[],description:'',inputFormat:'',outputFormat:'',constraints:'',sourcePlatform:'原创',sourceUrl:'',sourceId:'',sourceNote:'',modes:['STDIO'],defaultMode:'STDIO',checker:'TOKENS',profiles,references,cases:[]} }
function normalize(value){const defaults=blankPack();const p={...defaults,...value};p.profiles={...defaults.profiles,...value.profiles};p.references={...defaults.references,...value.references};for(const key of Object.keys(defaults.profiles)){p.profiles[key]={...defaults.profiles[key],...p.profiles[key]};p.references[key]={...defaults.references[key],...p.references[key]}}if(!Array.isArray(p.cases))throw new Error('测试集格式无效');return p}
async function load(){loading.value=true;try{const {data}=await request.get('/api/admin/oj/problems',{params:{keyword:keyword.value,difficulty:difficulty.value,page:page.value}});rows.value=data.records;total.value=data.total}catch(e){ElMessage.error(e.message||'加载失败')}finally{loading.value=false}}
async function loadSettings(){try{const [a,b]=await Promise.all([request.get('/api/admin/oj/languages'),request.get('/api/admin/oj/health')]);settings.value=a.data;health.value=b.data}catch(e){ElMessage.error(e.message||'加载失败')}}
function create(){++formatGeneration;templatesLoading.value=false;templateMode.value='STDIO';templateField.value='starter';editingId.value=null;revision.value=null;pack.value=blankPack();tagsText.value='';editorTab.value='content';casePage.value=1;validationJob.value=null;editorOpen.value=true}
async function edit(id,tab='content'){try{const {data}=await request.get(`/api/admin/oj/problems/${id}`);editingId.value=id;revision.value=data.revision;pack.value=normalize(data.pack);tagsText.value=pack.value.tags.join(', ');editorTab.value=tab;casePage.value=1;validationJob.value=data.validationJobId;editorOpen.value=true;templateMode.value=pack.value.defaultMode;templateField.value='starter';formatTemplates()}catch(e){ElMessage.error(e.message)}}
async function save(){saving.value=true;try{pack.value.tags=tagsText.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean);if(!pack.value.modes.includes(pack.value.defaultMode))pack.value.defaultMode=pack.value.modes[0];const {data}=editingId.value?await request.put(`/api/admin/oj/problems/${editingId.value}`,{revision:revision.value,pack:pack.value}):await request.post('/api/admin/oj/problems',pack.value);editingId.value=data.id;revision.value=data.revision;validationJob.value=null;editorOpen.value=false;ElMessage.success('已保存草稿');load()}catch(e){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
async function setStatus(row,status){try{await request.put(`/api/admin/oj/problems/${row.id}/status`,{status});ElMessage.success('状态已更新');load()}catch(e){ElMessage.error(e.message)}}
async function saveSettings(){try{await request.put('/api/admin/oj/languages',settings.value);ElMessage.success('语言配置已保存');load();loadSettings()}catch(e){ElMessage.error(e.message)}}
async function validate(row){try{const {data}=await request.post(`/api/admin/oj/problems/${row.id}/validate`);validating.value.add(row.id);report.value=data;reportOpen.value=true;poll(data.id,row.id)}catch(e){ElMessage.error(e.message)}}
async function poll(id,problemId){if(disposed)return;try{const {data}=await request.get(`/api/admin/oj/jobs/${id}`);if(disposed)return;report.value=data;if(['QUEUED','RUNNING'].includes(data.status)){const timer=setTimeout(()=>{timers.delete(timer);poll(id,problemId)},2000);timers.add(timer)}else{validating.value.delete(problemId);load();loadSettings()}}catch(e){validating.value.delete(problemId);ElMessage.error(e.message)}}
async function showLatestReport(){if(!validationJob.value)return ElMessage.info('暂无验证记录');try{report.value=(await request.get(`/api/admin/oj/jobs/${validationJob.value}`)).data;reportOpen.value=true;if(['QUEUED','RUNNING'].includes(report.value.status))poll(validationJob.value,editingId.value)}catch(e){ElMessage.error(e.message)}}
function addCase(){pack.value.cases.push({name:`用例 ${pack.value.cases.length+1}`,input:'',expectedOutput:'',sample:false});casePage.value=Math.ceil(pack.value.cases.length/10)}
async function readFile(file){if(!file)return null;if(file.size>4_000_000)throw new Error('JSON 文件不能超过 4 MB');return JSON.parse(await file.text())}
async function importPack(event){try{const value=await readFile(event.target.files[0]);if(!value)return;create();pack.value=normalize(value.pack||value);tagsText.value=pack.value.tags.join(', ');templateMode.value=pack.value.defaultMode;formatTemplates();ElMessage.success('已载入题目包，请检查后保存')}catch(e){ElMessage.error(e.message||'JSON 格式无效')}finally{event.target.value=''}}
async function importCases(event){try{const value=await readFile(event.target.files[0]);if(!value)return;const tests=Array.isArray(value)?value:value.cases;if(!Array.isArray(tests)||tests.length>500||tests.some(t=>typeof t.input!=='string'||typeof t.expectedOutput!=='string'))throw new Error('测试集须为用例数组，包含 name、input、expectedOutput、sample');pack.value.cases=tests.map((t,i)=>({...t,name:t.name||`用例 ${i+1}`,sample:!!t.sample}));casePage.value=1;ElMessage.success('已载入测试集，请保存题目')}catch(e){ElMessage.error(e.message)}finally{event.target.value=''}}
function exportCases(){const url=URL.createObjectURL(new Blob([JSON.stringify(pack.value.cases,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${pack.value.slug||'problem'}-cases.json`;a.click();URL.revokeObjectURL(url)}
onMounted(()=>{load();loadSettings()});onBeforeUnmount(()=>{disposed=true;++codeGeneration;clearInterval(monitorTimer);clearInterval(runTimer);timers.forEach(clearTimeout)})
</script>
